// Copies science bundles into public/bundles/ and writes public/bundles/index.json.
// Sources, in priority order:
//   1. ../data/bundles/*.json          (science branch output; fixture.json first)
//   2. ../app/data/polaris-source-*-v2.json (Codex source cases; raw inputs only)
//   3. public/bundles/demo-fixture.json (DEMO, generated by scripts/make_demo_fixture.py)
// The viewer never edits a bundle. It only lists what exists.
import { createHash } from 'node:crypto';
import { copyFileSync, existsSync, mkdirSync, readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { basename, dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const web = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const repo = resolve(web, '..');
const out = join(web, 'public', 'bundles');
mkdirSync(out, { recursive: true });

const entries = [];
function add(src, origin) {
  const name = basename(src);
  const dest = join(out, name);
  if (resolve(src) !== resolve(dest)) copyFileSync(src, dest);
  const bytes = readFileSync(dest);
  let status = 'UNKNOWN';
  let label = name;
  try {
    const j = JSON.parse(bytes.toString('utf8'));
    if (j?.schema === 'science-bundle-v2') {
      // Person A's format (a-science): one site per bundle
      status = j?.validation_status?.overall ?? status;
      label = `${j?.site?.name ?? j?.bundle_id} · science-bundle-v2 — ${name}`;
    } else {
      status = j?.validation?.status ?? status;
      const names = (j?.datasets ?? []).map((d) => d?.site?.name ?? d?.siteId);
      label = `${names.join(' + ')} — ${name}`;
    }
  } catch {
    status = 'UNREADABLE';
  }
  entries.push({ file: name, origin, status, label, sha256: createHash('sha256').update(bytes).digest('hex'), bytes: bytes.length });
}

const sci = join(repo, 'data', 'bundles');
if (existsSync(sci)) {
  const files = readdirSync(sci).filter((f) => f.endsWith('.json')).sort((a, b) => (a === 'fixture.json' ? -1 : b === 'fixture.json' ? 1 : a.localeCompare(b)));
  for (const f of files) add(join(sci, f), 'data/bundles (science branch)');
}
const appData = join(repo, 'app', 'data');
if (existsSync(appData)) {
  for (const f of readdirSync(appData).filter((f) => /^polaris-source-.*-v2\.json$/.test(f)).sort()) add(join(appData, f), 'app/data (Codex source case)');
}
const demo = join(out, 'demo-fixture.json');
if (existsSync(demo)) add(demo, 'DEMO fixture (synthetic)');

writeFileSync(join(out, 'index.json'), JSON.stringify({ generated: new Date().toISOString(), bundles: entries }, null, 2));
console.log(`bundles: ${entries.map((e) => `${e.file} [${e.status}]`).join(', ') || 'none'}`);
